const results = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && rg -n \"stylus-sdk|motsu|vm::|msg::|block::|evm::|#[[:space:]]*test|proptest|criterion|cargo-fuzz\" Cargo.toml Cargo.lock . --glob '!target/**' --glob '!**/.git/**' | head -n 260",workdir:"/tmp/bench/ws",yield_time_ms:10000,max_output_tokens:10000}),
  tools.exec_command({cmd:"rg --files -g 'Cargo.toml' -g '*.rs' -g '*.md' -g '*.toml' | head -n 240",workdir:"/tmp/bench/ws",yield_time_ms:10000,max_output_tokens:10000}),
  tools.web__run({search_query:[
    {q:"site:github.com/OffchainLabs/stylus-sdk-rs/releases 0.10.10"},
    {q:"site:github.com/OffchainLabs/stylus-sdk-rs 0.10.10 changelog"},
    {q:"site:docs.rs/stylus-sdk/0.10.10 stylus_sdk"}
  ],response_length:"long"})
]);
for (const r of results) text(JSON.stringify(r));

