        let mut inner = vec.grow();  // adds a new element accessible via `inner`
        inner.push(0.into());        // inner is a guard to a StorageVec<StorageU8>
    }

    fn nested_map(map: &mut StorageMap<u32, StorageVec<U8>>) {
        let mut slot = map.setter(0);
