import re, pathlib, collections
root=pathlib.Path('contracts/src')
files=list(root.rglob('*.rs'))+[pathlib.Path('templates/crypto-erc20/src/lib.rs')]
types=collections.Counter(); sigs=[]
for p in files:
 s=p.read_text()
 for m in re.finditer(r'#\[motsu::test\][\s\S]{0,1200}?fn\s+(\w+)\s*\(',s):
  i=m.end(); depth=1; j=i
  while j<len(s) and depth:
   if s[j]=='(': depth+=1
   elif s[j]==')': depth-=1
   j+=1
  params=s[i:j-1].strip()
  if params:
   for part in params.split(','):
    part=part.strip()
    if ':' in part:
     name,typ=part.split(':',1); types[typ.strip()]+=1
  sigs.append((str(p),m.group(1),params))
print('test function signatures:',len(sigs),'with params',sum(bool(x[2]) for x in sigs))
print('param types:')
for t,n in types.most_common(): print(n,t)
print('\nInteresting parameter signatures:')
for p,name,params in sigs:
 if params and (not all(t in params for t in ['Contract<']) or params.count('Contract<')>1): print(p,name,params.replace('\n',' '))
