import re,pathlib,collections
files=list(pathlib.Path('contracts/src').rglob('*.rs'))+[pathlib.Path('templates/crypto-erc20/src/lib.rs')]
names=collections.Counter()
for p in files:
 s=p.read_text()
 for m in re.finditer(r'#\[motsu::test\][\s\S]{0,1200}?fn\s+\w+\s*\(',s):
  i=m.end(); depth=1; j=i
  while j<len(s) and depth:
   if s[j]=='(':depth+=1
   elif s[j]==')':depth-=1
   j+=1
  for part in s[i:j-1].split(','):
   part=part.strip()
   if ':' in part:
    n,t=part.split(':',1)
    if t.strip()=='Address': names[n.strip()]+=1
print(names)
PY",workdir:"/tmp/bench/ws",yield_time_ms:10000,max_output_tokens:4000}); text(r.output);

