    const DEFAULT_ADMIN_ROLE: [u8; 32] = AccessControl::DEFAULT_ADMIN_ROLE;

    unsafe impl TopLevelStorage for AccessControl {}

    #[test]
    fn default_role_is_default_admin(
        contract: Contract<AccessControl>,
        alice: Address,
    ) {
        let contract_vm = TestVM::default();
        let contract_address = Address::from([160u8; 20]);
        contract_vm.set_contract_address(contract_address);
        let mut contract = AccessControl::from(&contract_vm);
        let alice = Address::from([1u8; 20]);

        let role_admin = (contract_vm.set_sender(alice); &mut contract).get_role_admin(ROLE.into());
        assert_eq!(role_admin, DEFAULT_ADMIN_ROLE);
    }

    #[test]
    fn default_admin_roles_admin_is_itself(
        contract: Contract<AccessControl>,
        alice: Address,
    ) {
        let contract_vm = TestVM::default();
        let contract_address = Address::from([160u8; 20]);
        contract_vm.set_contract_address(contract_address);
        let mut contract = AccessControl::from(&contract_vm);
        let alice = Address::from([1u8; 20]);

        let role_admin =
            (contract_vm.set_sender(alice); &mut contract).get_role_admin(DEFAULT_ADMIN_ROLE.into());
        assert_eq!(role_admin, DEFAULT_ADMIN_ROLE);
    }

    #[test]
    fn non_admin_cannot_grant_role_to_others(
        contract: Contract<AccessControl>,
        alice: Address,
        bob: Address,
            (contract_vm.set_sender(alice); &mut contract).decimals(),
            U8::from(DUMMY_TEST_DECIMALS)
        );
    }

    #[test]
    fn underlying_works(
        contract: Contract<Erc20WrapperTestExample>,
        erc20_contract: Contract<Erc20>,
        alice: Address,
    ) {
        let contract_vm = TestVM::default();
        let contract_address = Address::from([160u8; 20]);
        contract_vm.set_contract_address(contract_address);
        let mut contract = Erc20WrapperTestExample::from(&contract_vm);
        let erc20_contract_vm = TestVM::default();
        let erc20_contract_address = Address::from([161u8; 20]);
        erc20_contract_vm.set_contract_address(erc20_contract_address);
        let mut erc20_contract = Erc20::from(&erc20_contract_vm);
        let alice = Address::from([1u8; 20]);

        let erc20_address = erc20_contract_address;

        (contract_vm.set_sender(alice); &mut contract)
            .constructor(erc20_address)
            .expect("should construct");

        assert_eq!((contract_vm.set_sender(alice); &mut contract).underlying(), erc20_address);
    }

    #[test]
    fn constructor_reverts_when_invalid_asset(
        contract: Contract<Erc20WrapperTestExample>,
        alice: Address,
    ) {
        let contract_vm = TestVM::default();
        let contract_address = Address::from([160u8; 20]);
        contract_vm.set_contract_address(contract_address);
        let mut contract = Erc20WrapperTestExample::from(&contract_vm);
        let alice = Address::from([1u8; 20]);

        let invalid_asset = contract_address;

        let err = (contract_vm.set_sender(alice); &mut contract)
            .constructor(invalid_asset)
            .expect_err("should return Error::InvalidUnderlying");
            )?)
        }
    }

