#[test]
fn recover_reverts_when_invalid_underlying() {
    let contract_vm = TestVM::default();
    let contract_address = Address::from([160u8; 20]);
    contract_vm.set_contract_address(contract_address);
    let mut contract = Erc20WrapperTestExample::from(&contract_vm);
    let alice = Address::from([1u8; 20]);

    let invalid_underlying = alice;
    ({ contract_vm.set_sender(alice); &mut contract }).wrapper.underlying.set(invalid_underlying);
    contract_vm.set_contract_address(contract_address);
    let mut contract = Erc721WrapperTestExample::from(&contract_vm);
    let erc721_contract_vm = TestVM::default();
    let erc721_contract_address = Address::from([161u8; 20]);
    erc721_contract_vm.set_contract_address(erc721_contract_address);
    let mut erc721_contract = Erc721::from(&erc721_contract_vm);
    let alice = Address::from([1u8; 20]);

    let token_id = random_token_ids(1)[0];

    ({ contract_vm.set_sender(alice); &mut contract }).constructor(erc721_contract_address);

    // Mint an "unexpected" wrapped token.
    ({ contract_vm.set_sender(alice); &mut contract })
        .erc721
        ._mint(alice, token_id)
        .expect("should mint {token_id} for {alice}");

    let operator = alice;

    let err = contract
        .sender(erc721_contract_address)
        .on_erc721_received(operator, alice, token_id, vec![].into())
        .expect_err("should return Error::Erc721");

    assert_eq!(
        err,
        erc721::ERC721InvalidSender { sender: Address::ZERO }.abi_encode()
    );
}

