        let balance = ({ erc20_vm.set_sender(alice); &mut erc20 }).balance_of(alice);
        assert_eq!(balance, U256::ZERO);
        let balance = ({ erc20_vm.set_sender(alice); &mut erc20 }).balance_of(bob);
        assert_eq!(balance, value);
    }

