            spender: Address,
            value: U256,
        ) -> Result<(), Self::Error> {
            self.safe_erc20.force_approve(token, spender, value)
        }

        fn transfer_and_call_relaxed(
            &mut self,
            token: Address,
            to: Address,
            value: U256,
            data: Bytes,
        ) -> Result<(), Self::Error> {
            self.safe_erc20.transfer_and_call_relaxed(token, to, value, data)
        }

        fn transfer_from_and_call_relaxed(
            &mut self,
            token: Address,
            from: Address,
            to: Address,
            value: U256,
            data: Bytes,
        ) -> Result<(), Self::Error> {
            self.safe_erc20
                .transfer_from_and_call_relaxed(token, from, to, value, data)
        }

        fn approve_and_call_relaxed(
            &mut self,
            token: Address,
            spender: Address,
            value: U256,
            data: Bytes,
        ) -> Result<(), Self::Error> {
            self.safe_erc20
                .approve_and_call_relaxed(token, spender, value, data)
        }
    }

    #[test]
    fn try_safe_transfer() {
        let contract_vm = TestVM::default();
        let contract_address = Address::from([160u8; 20]);
        contract_vm.set_contract_address(contract_address);
        let mut contract = SafeErc20Example::from(&contract_vm);
        let erc20_vm = TestVM::default();
        let erc20_address = Address::from([161u8; 20]);
        erc20_vm.set_contract_address(erc20_address);
        let mut erc20 = Erc20::from(&erc20_vm);
        let alice = Address::from([1u8; 20]);

        let token = erc20_address;
        let value = U256::from(1);
        ({ erc20_vm.set_sender(alice); &mut erc20 })._mint(contract_address, value).unwrap();

        let balance = ({ erc20_vm.set_sender(alice); &mut erc20 }).balance_of(contract_address);
        assert_eq!(balance, value);
        let balance = ({ erc20_vm.set_sender(alice); &mut erc20 }).balance_of(alice);
        assert_eq!(balance, U256::ZERO);

        let result =
            ({ contract_vm.set_sender(alice); &mut contract }).try_safe_transfer(token, alice, value);
        assert!(result);

        let balance = ({ erc20_vm.set_sender(alice); &mut erc20 }).balance_of(contract_address);
        assert_eq!(balance, U256::ZERO);
        let balance = ({ erc20_vm.set_sender(alice); &mut erc20 }).balance_of(alice);
        assert_eq!(balance, value);
    }

    #[test]
    fn try_safe_transfer_from() {
        let contract_vm = TestVM::default();
        let contract_address = Address::from([160u8; 20]);
        contract_vm.set_contract_address(contract_address);
        let mut contract = SafeErc20Example::from(&contract_vm);
        let erc20_vm = TestVM::default();
        let erc20_address = Address::from([161u8; 20]);
        erc20_vm.set_contract_address(erc20_address);
        let mut erc20 = Erc20::from(&erc20_vm);
        let alice = Address::from([1u8; 20]);
        let bob = Address::from([2u8; 20]);

        let token = erc20_address;
        let value = U256::from(1);
        ({ erc20_vm.set_sender(alice); &mut erc20 })._mint(alice, value).unwrap();
        ({ erc20_vm.set_sender(alice); &mut erc20 }).approve(contract_address, value).unwrap();

        let balance = ({ erc20_vm.set_sender(alice); &mut erc20 }).balance_of(alice);
        assert_eq!(balance, value);
        let balance = ({ erc20_vm.set_sender(alice); &mut erc20 }).balance_of(bob);
        assert_eq!(balance, U256::ZERO);

        let result = ({ contract_vm.set_sender(alice); &mut contract })
            .try_safe_transfer_from(token, alice, bob, value);
        assert!(result);

        let balance = ({ erc20_vm.set_sender(alice); &mut erc20 }).balance_of(alice);
        assert_eq!(balance, U256::ZERO);
        let balance = ({ erc20_vm.set_sender(alice); &mut erc20 }).balance_of(bob);
        assert_eq!(balance, value);
    }

    #[test]
    fn safe_decrease_allowance_reverts_on_no_code_address() {
        let contract_vm = TestVM::default();
        let contract_address = Address::from([160u8; 20]);
        if fee.is_zero() || flash_fee_receiver.is_zero() {
            erc20._burn(receiver, allowance)?;
        } else {
            erc20._burn(receiver, value)?;
            erc20._transfer(receiver, flash_fee_receiver, fee)?;
        }

        Ok(true)
    }
