        function balanceOf(address account) external view returns (uint256);
        function totalSupply() external view returns (uint256);
        function mint(address to, uint256 value) external;
        function transfer(address to, uint256 value) external returns (bool);
    }
}

use crate::test_utils::assert_emitted;

#[test]
fn constructs() {
    let proxy_vm = TestVM::default();
    let proxy_address = Address::from([160u8; 20]);
    proxy_vm.set_contract_address(proxy_address);
    let mut proxy = BeaconProxyExample::from(&proxy_vm);
    let beacon_vm = TestVM::default();
    let beacon_test_address = Address::from([161u8; 20]);
    beacon_vm.set_contract_address(beacon_test_address);
    let mut beacon = Beacon::from(&beacon_vm);
    let erc20_vm = TestVM::default();
    let erc20_address = Address::from([162u8; 20]);
    erc20_vm.set_contract_address(erc20_address);
    let mut erc20 = Erc20Example::from(&erc20_vm);
    let alice = Address::from([1u8; 20]);

    ({
        beacon_vm.set_sender(alice);
        &mut beacon
    })
    .constructor(erc20_address);

    ({
        proxy_vm.set_sender(alice);
        &mut proxy
    })
    .constructor(beacon_test_address, vec![].into())
    .unwrap();

    let implementation = ({
        proxy_vm.set_sender(alice);
        &mut proxy
    })
    .implementation()
    .expect("should be able to get implementation");
    assert_eq!(implementation, erc20_address);

    let actual_beacon_address = ({
        proxy_vm.set_sender(alice);
        &mut proxy
    })
    .get_beacon();
    assert_eq!(actual_beacon_address, beacon_test_address);
}

#[test]
fn constructs_with_data() {
    let proxy_vm = TestVM::default();
    let proxy_address = Address::from([160u8; 20]);
    proxy_vm.set_contract_address(proxy_address);
    let mut proxy = BeaconProxyExample::from(&proxy_vm);
    let beacon_vm = TestVM::default();
    let beacon_test_address = Address::from([161u8; 20]);
    beacon_vm.set_contract_address(beacon_test_address);
    let mut beacon = Beacon::from(&beacon_vm);
    let erc20_vm = TestVM::default();
    let erc20_address = Address::from([162u8; 20]);
    erc20_vm.set_contract_address(erc20_address);
    let mut erc20 = Erc20Example::from(&erc20_vm);
    let alice = Address::from([1u8; 20]);

    ({
        beacon_vm.set_sender(alice);
        &mut beacon
    })
    .constructor(erc20_address);

    let amount = U256::from(1000);

    let data = IERC20::mintCall {
        to: alice,
        value: amount,
    }
    .abi_encode();

    ({
        proxy_vm.set_sender(alice);
        &mut proxy
    })
    .constructor(beacon_test_address, data.into())
    .expect("should be able to construct");

    let implementation = ({
        proxy_vm.set_sender(alice);
        &mut proxy
    })
    .implementation()
    .expect("should be able to get implementation");
    assert_eq!(implementation, erc20_address);

    let actual_beacon_address = ({
        proxy_vm.set_sender(alice);
        &mut proxy
    })
    .get_beacon();
    assert_eq!(actual_beacon_address, beacon_test_address);

    let balance_of_alice_call = IERC20::balanceOfCall { account: alice }.abi_encode();
    let balance = ({
        proxy_vm.set_sender(alice);
        &mut proxy
    })
    .fallback(&balance_of_alice_call)
    .expect("should be able to get balance");
    assert_eq!(balance, amount.abi_encode());

    let total_supply_call = IERC20::totalSupplyCall {}.abi_encode();
    let total_supply = ({
        proxy_vm.set_sender(alice);
        &mut proxy
    })
    .fallback(&total_supply_call)
    .expect("should be able to get total supply");
    assert_eq!(total_supply, amount.abi_encode());
}

