    #[test]
    fn try_safe_transfer() {
        let contract_vm = TestVM::default();
        let contract_address = Address::from([160u8; 20]);
        contract_vm.set_contract_address(contract_address);
        let mut contract = SafeErc20Example::from(&contract_vm);
        let erc20_vm = TestVM::default();
        let erc20_address = Address::from([161u8; 20]);
        erc20_vm.set_contract_address(erc20_address);
        let mut erc20 = Erc20::from(&erc20_vm);
        let alice = Address::from([1u8; 20]);

        let token = erc20_address;
        let value = U256::from(1);
        ({
            erc20_vm.set_sender(alice);
            &mut erc20
        })
        ._mint(contract_address, value)
        .unwrap();

        let balance = ({
            erc20_vm.set_sender(alice);
            &mut erc20
        })
        .balance_of(contract_address);
        assert_eq!(balance, value);
        let balance = ({
            erc20_vm.set_sender(alice);
            &mut erc20
        })
        .balance_of(alice);
        assert_eq!(balance, U256::ZERO);

        let result = ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .try_safe_transfer(token, alice, value);
        assert!(result);

        let balance = ({
            erc20_vm.set_sender(alice);
            &mut erc20
        })
        .balance_of(contract_address);
        assert_eq!(balance, U256::ZERO);
        let balance = ({
            erc20_vm.set_sender(alice);
            &mut erc20
