667:    use crate::token::erc20::{Erc20, IErc20};
    /// # Errors
    ///
    /// * [`Error::SafeErc20FailedOperation`] - If the `token` address is not a
    ///   the contract fails to execute the call or the call returns
    ///   value that is not `true`.
    fn call_optional_return<T: HostAccess>(
        context: &T,
        token: Address,
        call: &impl SolCall,
    ) -> Result<(), Error> {
        if context.vm().code_size(token) == 0 {
            return Err(Error::SafeErc20FailedOperation(
                SafeErc20FailedOperation { token },
            ));
        }

        // Raw calls do not apply the SDK's automatic cache policy. Flush and
        // invalidate first so any reentrant call observes the latest state.
        context.vm().flush_cache(true);

        let result = unsafe {
            RawCall::new(context.vm())
                .limit_return_data(0, BOOL_TYPE_SIZE)
                .call(token, &call.abi_encode())
        };

        match result {
            Ok(data)
                if data.is_empty()
                    || Bool::abi_decode_validate(&data)
                        .is_ok_and(|success| success) =>
            {
                Ok(())
            }
            _ => Err(SafeErc20FailedOperation { token }.into()),
        }
    }

