#[test]
fn withdraw_to_works() {
    let contract_vm = TestVM::default();
    let contract_address = Address::from([160u8; 20]);
    contract_vm.set_contract_address(contract_address);
    let mut contract = Erc721WrapperTestExample::from(&contract_vm);
    let erc721_contract_vm = TestVM::default();
    let erc721_contract_address = Address::from([161u8; 20]);
    erc721_contract_vm.set_contract_address(erc721_contract_address);
    let mut erc721_contract = Erc721::from(&erc721_contract_vm);
    let alice = Address::from([1u8; 20]);

    let tokens = 4;
    let token_ids = random_token_ids(tokens);

    ({
        contract_vm.set_sender(alice);
        &mut contract
    })
    .constructor(erc721_contract_address);

    for token_id in &token_ids {
        ({
            erc721_contract_vm.set_sender(alice);
            &mut erc721_contract
        })
        ._mint(alice, *token_id)
        .expect("should mint {token_id} for {alice}");

        ({
            erc721_contract_vm.set_sender(alice);
            &mut erc721_contract
        })
        .approve(contract_address, *token_id)
        .expect("should approve {token_id} for {contract_address}");
    }

    assert!(({
        contract_vm.set_sender(alice);
        &mut contract
    })
    .deposit_for(alice, token_ids.clone())
    .expect("should deposit"));

    let initial_balance = ({
        erc721_contract_vm.set_sender(alice);
        &mut erc721_contract
    })
    .balance_of(alice)
    .unwrap();
    let initial_wrapped_balance = ({
        contract_vm.set_sender(alice);
        &mut contract
    })
    .erc721
    .balance_of(alice)
    .unwrap();

    let initial_contract_balance = ({
        erc721_contract_vm.set_sender(alice);
        &mut erc721_contract
    })
    .balance_of(contract_address)
    .unwrap();

    assert!(({
        contract_vm.set_sender(alice);
        &mut contract
    })
    .withdraw_to(alice, token_ids.clone())
    .expect("should withdraw"));

    for token_id in token_ids {
        assert_emitted(
            &erc721_contract_vm,
            &erc721::Transfer {
                from: contract_address,
                to: alice,
                token_id,
            },
        );

        assert_emitted(
            &contract_vm,
            &erc721::Transfer {
                from: alice,
                to: Address::ZERO,
                token_id,
            },
        );
    }

    assert_eq!(
        ({
            erc721_contract_vm.set_sender(alice);
            &mut erc721_contract
        })
        .balance_of(alice)
        .unwrap(),
        initial_balance + U256::from(tokens)
    );

    assert_eq!(
        ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .erc721
        .balance_of(alice)
        .unwrap(),
        initial_wrapped_balance - U256::from(tokens)
    );

    assert_eq!(
        (erc721_contract_vm.set_sender(contract_address); &mut erc721_contract)
            .balance_of(contract_address)
            .unwrap(),
        initial_contract_balance - U256::from(tokens)
    );
}

