    .approve(contract_address, amount)
    .expect("should approve");

    ({
        contract_vm.set_sender(alice);
        &mut contract
    })
    .deposit_for(alice, amount)
    .expect("should deposit");

    let exceeding_value = amount + uint!(1_U256);

    let err = ({
        contract_vm.set_sender(alice);
        &mut contract
    })
    .withdraw_to(alice, exceeding_value)
    .expect_err("should return Error::SafeErc20");

    assert!(matches!(
        err,
        Error::InsufficientBalance(
            erc20::ERC20InsufficientBalance {
                sender,
                balance,
                needed
            }
        ) if sender == alice && balance == amount && needed == exceeding_value
    ));
}

#[test]
fn withdraw_to_works() {
    let contract_vm = TestVM::default();
    let contract_address = Address::from([160u8; 20]);
    contract_vm.set_contract_address(contract_address);
    let mut contract = Erc20WrapperTestExample::from(&contract_vm);
    let erc20_contract_vm = TestVM::default();
    let erc20_contract_address = Address::from([161u8; 20]);
    erc20_contract_vm.set_contract_address(erc20_contract_address);
    let mut erc20_contract = Erc20::from(&erc20_contract_vm);
    let alice = Address::from([1u8; 20]);

    let amount = uint!(10_U256);

    ({
        contract_vm.set_sender(alice);
        &mut contract
    })
    .constructor(erc20_contract_address)
    .expect("should construct");

    ({
        erc20_contract_vm.set_sender(alice);
        &mut erc20_contract
    })
    ._mint(alice, amount)
    .expect("should mint");

    ({
        erc20_contract_vm.set_sender(alice);
        &mut erc20_contract
    })
    .approve(contract_address, amount)
    .expect("should approve");

    ({
        contract_vm.set_sender(alice);
        &mut contract
    })
    .deposit_for(alice, amount)
    .expect("should deposit");

    let initial_balance = ({
        erc20_contract_vm.set_sender(alice);
        &mut erc20_contract
    })
    .balance_of(alice);
    let initial_wrapped_balance = ({
        contract_vm.set_sender(alice);
        &mut contract
    })
    .erc20
    .balance_of(alice);

    let initial_contract_balance = ({
        erc20_contract_vm.set_sender(alice);
        &mut erc20_contract
    })
    .balance_of(contract_address);

    let initial_wrapped_supply = ({
        contract_vm.set_sender(alice);
        &mut contract
    })
    .erc20
    .total_supply();

    assert!(({
        contract_vm.set_sender(alice);
        &mut contract
    })
    .withdraw_to(alice, amount)
    .expect("should withdraw"));

    assert_emitted(
        &contract_vm,
        &erc20::Transfer {
            from: alice,
            to: Address::ZERO,
            value: amount,
        },
    );

    assert_emitted(
        &erc20_contract_vm,
        &erc20::Transfer {
            from: contract_address,
            to: alice,
            value: amount,
        },
    );

    assert_eq!(
        ({
            erc20_contract_vm.set_sender(alice);
            &mut erc20_contract
        })
        .balance_of(alice),
        initial_balance + amount
    );

    assert_eq!(
        ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .erc20
        .balance_of(alice),
        initial_wrapped_balance - amount
    );

    assert_eq!(
        (erc20_contract_vm.set_sender(contract_address); &mut erc20_contract)
            .balance_of(contract_address),
        initial_contract_balance - amount
    );

    assert_eq!(
        ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .erc20
        .total_supply(),
        initial_wrapped_supply - amount
    );
}

