def replace_fn(name, body):
    global s
    fnpos=s.index(f'fn {name}() {{')
    start=s.rfind('    #[test]',0,fnpos)
    next_test=s.find('    #[test]',fnpos)
    if next_test < 0: next_test=s.rfind('\n}', fnpos)
    s=s[:start]+body.rstrip()+"\n\n"+s[next_test:]

