#[cfg(test)]
mod tests {
    use alloy_sol_types::{SolCall, SolError, SolValue};
    use alloy_primitives::{aliases::B32, uint};
    use stylus_sdk::testing::TestVM;

    use super::*;

    const DUMMY_TEST_DECIMALS: u8 = 12;

    fn mock_transfer_from(
        vm: &TestVM,
        token: Address,
        from: Address,
        to: Address,
        value: U256,
        result: Result<Vec<u8>, Vec<u8>>,
    ) {
        vm.set_code(token, vec![1]);
        vm.mock_call(
            token,
            Erc20Interface::transferFromCall { from, to, value }.abi_encode(),
            U256::ZERO,
            result,
        );
    }

    fn mock_transfer(
        vm: &TestVM,
        token: Address,
        to: Address,
        value: U256,
        result: Result<Vec<u8>, Vec<u8>>,
    ) {
        vm.set_code(token, vec![1]);
        vm.mock_call(
            token,
            Erc20Interface::transferCall { to, value }.abi_encode(),
            U256::ZERO,
            result,
