    #[test]
    fn delegate() {
        let proxy_vm = TestVM::default();
        let proxy_address = Address::from([160u8; 20]);
        proxy_vm.set_contract_address(proxy_address);
        let mut proxy = ProxyExample::from(&proxy_vm);
        let erc20_vm = TestVM::default();
        let erc20_address = Address::from([161u8; 20]);
        erc20_vm.set_contract_address(erc20_address);
        let mut erc20 = Erc20Example::from(&erc20_vm);
        let alice = Address::from([1u8; 20]);
        let bob = Address::from([2u8; 20]);

        ({
            proxy_vm.set_sender(alice);
            &mut proxy
        })
        .constructor(erc20_address);

        // verify initial balance is [`U256::ZERO`].
        let balance_of_alice_call = IERC20::balanceOfCall { account: alice }.abi_encode();
        let balance = ({
            proxy_vm.set_sender(alice);
            &mut proxy
        })
        .fallback(&balance_of_alice_call)
        .expect("should be able to get balance");
        assert_eq!(balance, U256::ZERO.abi_encode());

        let total_supply_call = IERC20::totalSupplyCall {}.abi_encode();
        let total_supply = ({
            proxy_vm.set_sender(alice);
            &mut proxy
        })
        .fallback(&total_supply_call)
        .expect("should be able to get total supply");
        assert_eq!(total_supply, U256::ZERO.abi_encode());

        // mint 1000 tokens.
        let amount = U256::from(1000);

        let mint_call = IERC20::mintCall {
            to: alice,
            value: amount,
        }
        .abi_encode();
        ({
            proxy_vm.set_sender(alice);
            &mut proxy
        })
        .fallback(&mint_call)
        .expect("should be able to mint");
        // TODO: this should assert that the transfer event was emitted on the
        // proxy
        // https://github.com/OpenZeppelin/stylus-test-helpers/issues/111
        assert_emitted(
            &erc20_vm,
            &erc20::Transfer {
                from: Address::ZERO,
                to: alice,
                value: amount,
            },
        );

        // check that the balance can be accurately fetched through the proxy.
        let balance = ({
            proxy_vm.set_sender(alice);
            &mut proxy
        })
        .fallback(&balance_of_alice_call)
        .expect("should be able to get balance");
        assert_eq!(balance, amount.abi_encode());

        let total_supply = ({
            proxy_vm.set_sender(alice);
            &mut proxy
        })
        .fallback(&total_supply_call)
        .expect("should be able to get total supply");
        assert_eq!(total_supply, amount.abi_encode());

        // check that the balance can be transferred through the proxy.
        let transfer_call = IERC20::transferCall {
            to: bob,
            value: amount,
        }
        .abi_encode();
        ({
            proxy_vm.set_sender(alice);
            &mut proxy
        })
        .fallback(&transfer_call)
        .expect("should be able to transfer");

        // TODO: this should assert that the transfer event was emitted on the
        // proxy
        // https://github.com/OpenZeppelin/stylus-test-helpers/issues/111
        assert_emitted(
            &erc20_vm,
            &erc20::Transfer {
                from: alice,
                to: bob,
                value: amount,
            },
        );

        let balance = ({
            proxy_vm.set_sender(alice);
            &mut proxy
        })
        .fallback(&balance_of_alice_call)
        .expect("should be able to get balance");
        assert_eq!(balance, U256::ZERO.abi_encode());

        let balance_of_bob_call = IERC20::balanceOfCall { account: bob }.abi_encode();
        let balance = ({
            proxy_vm.set_sender(alice);
            &mut proxy
        })
        .fallback(&balance_of_bob_call)
        .expect("should be able to get balance");
        assert_eq!(balance, amount.abi_encode());

        let total_supply = ({
            proxy_vm.set_sender(alice);
            &mut proxy
        })
        .fallback(&total_supply_call)
        .expect("should be able to get total supply");
        assert_eq!(total_supply, amount.abi_encode());
    }

