    #[storage]
    struct Erc20Example {
        erc20: Erc20,
    }

    #[public]
    #[implements(IErc20<Error = erc20::Error>)]
    impl Erc20Example {
        fn mint(&mut self, to: Address, value: U256) -> Result<(), erc20::Error> {
            self.erc20._mint(to, value)
        }
    }

    unsafe impl TopLevelStorage for Erc20Example {}

    #[public]
    impl IErc20 for Erc20Example {
        type Error = erc20::Error;

        fn balance_of(&self, account: Address) -> U256 {
            self.erc20.balance_of(account)
        }

        fn total_supply(&self) -> U256 {
            self.erc20.total_supply()
        }

        fn transfer(&mut self, to: Address, value: U256) -> Result<bool, Self::Error> {
            self.erc20.transfer(to, value)
        }

        fn transfer_from(
            &mut self,
            from: Address,
            to: Address,
            value: U256,
        ) -> Result<bool, Self::Error> {
            self.erc20.transfer_from(from, to, value)
        }

        fn allowance(&self, owner: Address, spender: Address) -> U256 {
            self.erc20.allowance(owner, spender)
        }

        fn approve(&mut self, spender: Address, value: U256) -> Result<bool, Self::Error> {
            self.erc20.approve(spender, value)
        }
    }

    sol! {
        interface IERC20 {
            function balanceOf(address account) external view returns (uint256);
            function totalSupply() external view returns (uint256);
            function mint(address to, uint256 value) external;
            function transfer(address to, uint256 value) external returns (bool);
        }
    }

    use crate::test_utils::assert_emitted;

    #[test]
    fn constructs() {
        let proxy_vm = TestVM::default();
        let proxy_address = Address::from([160u8; 20]);
        proxy_vm.set_contract_address(proxy_address);
        let mut proxy = Erc1967ProxyExample::from(&proxy_vm);
        let erc20_vm = TestVM::default();
        let erc20_address = Address::from([161u8; 20]);
        erc20_vm.set_contract_address(erc20_address);
        let mut erc20 = Erc20Example::from(&erc20_vm);
        let alice = Address::from([1u8; 20]);

        ({
            proxy_vm.set_sender(alice);
            &mut proxy
        })
        .constructor(erc20_address, vec![].into())
        .expect("should be able to construct");

        let implementation = ({
            proxy_vm.set_sender(alice);
            &mut proxy
        })
        .implementation()
        .expect("should be able to get implementation");
        assert_eq!(implementation, erc20_address);
    }

    #[test]
    fn constructs_with_data() {
        let proxy_vm = TestVM::default();
        let proxy_address = Address::from([160u8; 20]);
        proxy_vm.set_contract_address(proxy_address);
        let mut proxy = Erc1967ProxyExample::from(&proxy_vm);
        let erc20_vm = TestVM::default();
        let erc20_address = Address::from([161u8; 20]);
        erc20_vm.set_contract_address(erc20_address);
        let mut erc20 = Erc20Example::from(&erc20_vm);
        let alice = Address::from([1u8; 20]);

        let amount = U256::from(1000);

        let data = IERC20::mintCall {
            to: alice,
            value: amount,
        }
        .abi_encode();

        ({
            proxy_vm.set_sender(alice);
            &mut proxy
        })
        .constructor(erc20_address, data.into())
        .expect("should be able to construct");

        let implementation = ({
            proxy_vm.set_sender(alice);
            &mut proxy
        })
        .implementation()
        .expect("should be able to get implementation");
        assert_eq!(implementation, erc20_address);

        let balance_of_alice_call = IERC20::balanceOfCall { account: alice }.abi_encode();
        let balance = ({
            proxy_vm.set_sender(alice);
            &mut proxy
        })
        .fallback(&balance_of_alice_call)
        .expect("should be able to get balance");
        assert_eq!(balance, amount.abi_encode());

        let total_supply_call = IERC20::totalSupplyCall {}.abi_encode();
        let total_supply = ({
            proxy_vm.set_sender(alice);
            &mut proxy
