impl CallAccess for TestVM {
    fn call(
        &self,
        _context: &dyn MutatingCallContext,
        to: Address,
        data: &[u8],
    ) -> Result<Vec<u8>, Error> {
        self.state
            .borrow()
            .call_returns
            .get(&(to, data.to_vec()))
            .cloned()
            .map(|opt| match opt {
                Ok(data) => Ok(data),
                Err(data) => Err(Error::Revert(data)),
            })
            .unwrap_or(Ok(Vec::new()))
    }

    unsafe fn delegate_call(
        &self,
        _context: &dyn MutatingCallContext,
        to: Address,
        data: &[u8],
    ) -> Result<Vec<u8>, Error> {
        self.state
            .borrow()
            .delegate_call_returns
            .get(&(to, data.to_vec()))
            .cloned()
            .map(|opt| match opt {
                Ok(data) => Ok(data),
                Err(data) => Err(Error::Revert(data)),
            })
            .unwrap_or(Ok(Vec::new()))
    }

    fn static_call(
        &self,
        _context: &dyn StaticCallContext,
        to: Address,
        data: &[u8],
    ) -> Result<Vec<u8>, Error> {
        self.state
            .borrow()
            .static_call_returns
            .get(&(to, data.to_vec()))
            .cloned()
            .map(|opt| match opt {
                Ok(data) => Ok(data),
                Err(data) => Err(Error::Revert(data)),
            })
            .unwrap_or(Ok(Vec::new()))
    }
}

