const r = await tools.exec_command({cmd:"python3 - <<'PY'
import subprocess,re
from pathlib import Path
files=subprocess.check_output(['git','ls-tree','-r','--name-only','HEAD','contracts/src','templates/crypto-erc20/src/lib.rs'],text=True).splitlines()
def test_fns(s):
 lines=s.splitlines(); out=[]
 for i,l in enumerate(lines):
  if not re.match(r'\s*#\[(?:test|motsu::test)\]',l): continue
  kind='motsu' if 'motsu' in l else 'test'; ignored=False
  for j in range(i+1,min(i+30,len(lines))):
   q=lines[j].strip()
   if re.match(r'#\[(?:test|motsu::test)\]',q): break
   if q.startswith('#[ignore'): ignored=True
   m=re.match(r'(?:pub(?:\([^)]*\))?\s+)?(?:async\s+)?fn\s+([\w]+)\s*\(',q)
   if m:
    out.append((m.group(1),kind,ignored));break
 return out
base={}; curr={}
for f in files:
 s=subprocess.check_output(['git','show',f'HEAD:{f}'],text=True)
 base[f]=test_fns(s)
 p=Path(f)
 curr[f]=test_fns(p.read_text()) if p.exists() else []
B={(f,n) for f,x in base.items() for n,_,_ in x}; C={(f,n) for f,x in curr.items() for n,_,_ in x}
print('HEAD tests',len(B),'Motsu',sum(k=='motsu' for x in base.values() for _,k,_ in x),'ignored',sum(ig for x in base.values() for *_,ig in x))
print('Current tests',len(C),'Motsu',sum(k=='motsu' for x in curr.values() for _,k,_ in x),'ignored',sum(ig for x in curr.values() for *_,ig in x))
print('removed',sorted(B-C))
print('added',sorted(C-B))
PY",workdir:"/tmp/bench/ws",yield_time_ms:10000,max_output_tokens:7000});
text(r.output);

