    impl ResolvedCollisionContract {
        fn foo_bar(&self, _x: u64) -> Result<(), Vec<u8>> {
            Ok(())
        }

        #[selector(name = "fooBarAlt")]
        fn fooBar(&self, _x: u64) -> Result<(), Vec<u8>> {
            Ok(())
        }
    }
}

