                #deny_value
                let args = match <#decode_inputs as #SolType>::abi_decode_params_validate(input) {
                    Ok(args) => args,
                    Err(err) => {
                        internal::failed_to_decode_arguments(err);
                        return Some(Err(Vec::new()));
