  c=s[i];n=s[i+1] if i+1<len(s) else ''
  if state=='n':
   if c=='/' and n=='/':state='line';i+=2;continue
   if c=='/' and n=='*':state='block';block=1;i+=2;continue
   if c=='"':state='str';i+=1;continue
   if c==op:d+=1
   elif c==cl:
    d-=1
