/// Delegate calls the contract at the given address.
///
/// # Safety
///
/// A delegate call must trust the other contract to uphold safety requirements.
/// Though this function clears any cached values, the other contract may arbitrarily change
/// storage, spend ether, and do other things one should never blindly allow other contracts to do.
pub unsafe fn delegate_call<H: Host + ?Sized>(
    host: &H,
    context: impl MutatingCallContext,
    to: Address,
    data: &[u8],
) -> Result<Vec<u8>, Error> {
    host.flush_cache(true); // clear storage to persist changes, invalidating the cache

    RawCall::new_delegate(host)
        .gas(context.gas())
        .call(to, data)
        .map_err(Error::Revert)
}

/// Calls the contract at the given address.
pub fn call<H: Host + ?Sized>(
    host: &H,
    context: impl MutatingCallContext,
    to: Address,
    data: &[u8],
) -> Result<Vec<u8>, Error> {
    host.flush_cache(true); // clear storage to persist changes, invalidating the cache

    unsafe {
        RawCall::new_with_value(host, context.value())
            .gas(context.gas())
            .call(to, data)
            .map_err(Error::Revert)
    }
}

