mod test {
    use alloy_primitives::{Address, U256};
    use stylus_core::CallContext;
    use stylus_test::TestVM;

    use super::*;

    #[derive(Clone)]
    pub struct MyContract;
    impl CallContext for MyContract {
        fn gas(&self) -> u64 {
            0
        }
    }
    unsafe impl MutatingCallContext for MyContract {
        fn value(&self) -> U256 {
            U256::from(0)
        }
    }
    impl StaticCallContext for MyContract {}

    // Test that sol_interface! correctly decodes multi-value return types.
    // This is a regression test for a bug where multi-value returns were
    // double-wrapped in a tuple, causing ABI decode panics.
    // Uses a dynamic type (string) to ensure the encoding difference is detectable —
    // fixed-size-only tuples have identical encoding whether nested or not.
    stylus_proc::sol_interface! {
        interface IMultiReturn {
            function mixed() external view returns (string, uint256);
        }
    }

    #[test]
    fn test_sol_interface_multi_return() {
        use alloy_sol_types::SolType;

        let vm = TestVM::new();
        let target = Address::from([3u8; 20]);
        let iface = IMultiReturn::new(target);
        let ctx = MyContract {};

        // Encode the return data as the callee would: flat ABI params (string, uint256)
        let return_data = <(
            alloy_sol_types::sol_data::String,
            alloy_sol_types::sol_data::Uint<256>,
        ) as SolType>::abi_encode_params(&(
            alloc::string::String::from("hello"),
            U256::from(42),
        ));

        // The calldata for mixed() is just the 4-byte selector (no args)
        let selector = &alloy_primitives::keccak256("mixed()")[..4];
        vm.mock_static_call(target, selector.to_vec(), Ok(return_data));

        let (s, n) = iface.mixed(&vm, ctx).unwrap();
        assert_eq!(s, "hello");
        assert_eq!(n, U256::from(42));
    }

    #[test]
    fn test_calls() {
        let vm = TestVM::new();
        let contract = MyContract {};
        let target = Address::from([2u8; 20]);
        let data = vec![1, 2, 3, 4];
        let expected_return = vec![5, 6, 7, 8];

}

/// Revert on reentrancy unless explicitly enabled.
///
/// # Deprecated
///
/// This guard is redundant and will be removed in a future release.
/// Reentrancy safety is provided by automatic cache flushing in the
/// high-level call functions (`call`, `delegate_call`, `static_call`).
/// This guard indiscriminately blocks all reentrant calls, preventing
/// use cases that require them.
#[cfg(not(feature = "stylus-test"))]
#[deprecated(
    note = "this guard is redundant — reentrancy safety is provided by automatic cache flushing — and it prevents use cases that require reentrant calls. Will be removed in a future release."
)]
fn deny_reentrant() -> Option<syn::ExprIf> {
    cfg_if::cfg_if! {
        if #[cfg(feature = "reentrant")] {
            None
        } else {
            Some(parse_quote! {
                if host.msg_reentrant() {
                    return 1; // revert
                }
            })
        }
    }
}
- Add reproducible Docker build path to `cargo stylus deploy` — previously deploy always built locally even when `--no-verify` was omitted, making Docker verification unreliable on cross-platform setups

### Fixed

- Fix reproducible Docker builds for workspace projects: mount workspace root instead of CWD so workspace-level `Cargo.toml`, `Cargo.lock`, and path dependencies are available inside the container
- Fix `cargo stylus verify` not forwarding `--contract` flag to inner Docker invocation, causing incorrect contract selection in multi-contract workspaces
- Fix reproducible build failing when base Docker image exists locally but not on Docker Hub

## [0.10.5](https://github.com/OffchainLabs/stylus-sdk-rs/releases/tag/v0.10.5) - 2026-04-16

### Changed

- Deprecate `reentrant` feature flag and `deny_reentrant` entrypoint guard — reentrancy safety is provided by automatic storage cache flushing in high-level call functions, making the guard redundant
- Rewrite reentrancy documentation to center cache flushing as the primary safety mechanism

## [0.10.4](https://github.com/OffchainLabs/stylus-sdk-rs/releases/tag/v0.10.4) - 2026-04-09

### Fixed

- Fix `cargo stylus new` panic when installed from crates.io registry [#421](https://github.com/OffchainLabs/stylus-sdk-rs/pull/421)

## [0.10.3](https://github.com/OffchainLabs/stylus-sdk-rs/releases/tag/v0.10.3) - 2026-04-01

### New

- Detect ABI selector collisions at compile time within `#[public]` blocks [#401](https://github.com/OffchainLabs/stylus-sdk-rs/pull/401)

### Fixed

- Fix `sol_interface!` ABI decode panic on multi-value return types containing dynamic types (e.g. `returns (string, uint256)`) [#414](https://github.com/OffchainLabs/stylus-sdk-rs/pull/414)
- Fix `cargo stylus new` leaving projects in a broken state when dependency resolution fails [#416](https://github.com/OffchainLabs/stylus-sdk-rs/pull/416)
- Fix codehash-keepalive command sending read-only call instead of transaction [#411](https://github.com/OffchainLabs/stylus-sdk-rs/pull/411)

