    provider: &(impl Provider + WalletProvider),
    constructor: Option<&Constructor>,
) -> Result<Receipt> {
    let contract = Contract::try_from(package).wrap_err_with(|| {
        format!("{} is not a deployable Stylus contract", package.name)
    })?;
