    let wasm_file = temp_dir.path().join("contract.wasm");
    fs::write(&wasm_file, wasm.as_slice())?;
    Ok(check_wasm_file(
        &wasm_file,
        project_hash,
        None,
        None,
        &config.check,
        provider,
    )
    .await?)
}

fn build_from_package_dir(
    contract: &Contract,
    package_dir: &Path,
    build: &stylus_tools::core::build::BuildConfig,
) -> Result<PathBuf> {
    let _lock = BUILD_DIRECTORY_LOCK
        .lock()
