287	async fn deploy_status(
288	    status: ContractStatus,
289	    config: &DeploymentConfig,
290	    provider: &(impl Provider + WalletProvider),
291	    constructor: Option<&Constructor>,
292	) -> Result<Receipt> {
293	    let sender = provider.default_signer_address();
294	    let (receipt, contract_address) = if let Some(constructor) = constructor {
295	        let constructor_abi = AbiConstructor::parse(&constructor.signature)
296	            .wrap_err("invalid constructor signature")?;
297	        if constructor_abi.inputs.len() != constructor.args.len() {
298	            bail!(
299	                "constructor argument count mismatch: signature has {} inputs, got {} values",
300	                constructor_abi.inputs.len(),
301	                constructor.args.len()
302	            );
303	        }
304	
305	        let code = code_for_deployment(&status, config, provider).await?;
306	        let calldata = parse_tx_calldata(
307	            &code,
308	            &constructor_abi,
309	            U256::ZERO,
310	            constructor.args.clone(),
311	            config.deployer_salt,
312	            provider,
313	        )
314	        .await
315	        .wrap_err("failed to encode Stylus constructor call")?;
316	        let request = DeploymentRequest::new_with_args(
317	            sender,
318	            config.deployer_address,
319	            status.suggest_fee(),
320	            calldata,
321	            config.max_fee_per_gas_gwei,
322	        );
323	        let receipt = request.exec(provider).await.map_err(|err| {
324	            if contains_initialization_error_selector(&err) {
325	                eyre::Report::new(ContractInitializationError)
326	            } else {
327	                eyre::Report::new(err)
328	            }
329	        })?;
330	        let address = get_address_from_receipt(&receipt)?;
331	        (receipt, address)
332	    } else {
333	        let was_active = matches!(&status, ContractStatus::Active { .. });
334	        let code = code_for_deployment(&status, config, provider).await?;
335	        let receipt =
336	            DeploymentRequest::new(sender, &code, config.max_fee_per_gas_gwei)
337	                .exec(provider)
338	                .await?;
339	        let address = receipt.contract_address.ok_or_else(|| {
340	            eyre::eyre!("deployment receipt did not include contract address")
341	        })?;
342	        if !was_active {
343	            activation::activate_contract(
344	                address,
345	                &config.check.activation,
346	                provider,
347	            )
348	            .await?;
349	        }
350	        (receipt, address)
351	    };
352	
353	    Ok(Receipt { inner: receipt, contract_address })
354	}
