186	/// Check a workspace contract through the SDK pipeline, with an extra WAT
187	/// round trip after optional optimization for the pinned Nitro devnet parser.
188	async fn check_contract_for_devnet(
189	    contract: &Contract,
190	    config: &DeploymentConfig,
191	    provider: &impl Provider,
192	) -> Result<ContractStatus> {
193	    let wasm_opt = WasmOptConfig::resolve_for_contract(contract)?;
194	    let package_dir = contract
195	        .package
196	        .manifest_path
197	        .parent()
198	        .ok_or_else(|| eyre::eyre!("contract manifest has no parent directory"))?
199	        .as_std_path();
200	    let wasm_file = build_from_package_dir(contract, package_dir, &config.check.build)?;
201	    let project_hash = hash_project(
202	        package_dir,
203	        &config.check.project,
204	        &config.check.build,
205	        wasm_opt.as_ref(),
206	    )?;
207	    let raw_wasm = fs::read(&wasm_file)?;
208	    let optimized = stylus_tools::core::code::wasm::process_wasm(
209	        &raw_wasm,
210	        project_hash,
211	        wasm_opt.as_ref(),
212	    )?;
213	
214	    // Nitro 3.11.1 rejects the optional DataCount section even when the module
215	    // uses only memory.copy/fill. SDK processing does an initial WAT round trip
216	    // before Binaryen; this second SDK round trip removes DataCount if Binaryen
217	    // adds it. Reprocessing the metadata is harmless because the checker strips
218	    // and writes the project hash itself.
219	    let wasm = stylus_tools::core::code::wasm::process_wasm(
220	        optimized.as_slice(),
221	        project_hash,
222	        None,
223	    )?;
224	    let temp_dir = tempfile::tempdir()?;
225	    let wasm_file = temp_dir.path().join("contract.wasm");
226	    fs::write(&wasm_file, wasm.as_slice())?;
227	    Ok(check_wasm_file(
228	        &wasm_file,
229	        project_hash,
230	        None,
231	        None,
232	        &config.check,
233	        provider,
234	    )
235	    .await?)
236	}
